VALUES (11165, 'tt0066473', NULL, 'Tora! Tora! Tora!', 'Tora! Tora! Tora!', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/c311sN931DixuZRer0JGYCwpx9N.jpg', 'https://image.tmdb.org/t/p/original/z2mntgw06VvPybd1YlNBi5prg7N.jpg', 'In the summer of 1941, the United States and Japan seem on the brink of war after constant embargos and failed diplomacy come to no end. "Tora! Tora! Tora!", named after the code words used by the lead Japanese pilot to indicate they had surprised the Americans, covers the days leading up to the attack on Pearl Harbor, which plunged America into the Second World War.', NULL, NULL, 3.9582, 7.181, 0, 9.66, '2026-11-23 03:03:39', '2026-11-23 03:03:39')
