VALUES (2605, 'tt0091949', NULL, 'Short Circuit', 'Short Circuit', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/e3eimdUK6lLe0iaSlLrYVQF3yeL.jpg', 'https://image.tmdb.org/t/p/original/fytpsMuKVm8GynH0n3DCzIBp092.jpg', 'After a lightning bolt zaps a robot named Number 5, the lovable machine starts to think he''s human and escapes the lab. Hot on his trail is his designer, Newton, who hopes to get to Number 5 before the military does. In the meantime, a spunky animal lover mistakes the robot for an alien and takes him in, teaching her new guest about life on Earth.', NULL, NULL, 7.0822, 6.65, 0, 9.0175, '2026-07-15 12:01:52', '2026-11-23 03:03:39')
