VALUES (65798, 'tt4647692', NULL, 'Letterkenny', 'Letterkenny', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/zrB0Viy72GYKiLrtSs7SQVz5QWl.jpg', 'https://image.tmdb.org/t/p/original/wdHK7RZNIGfskbGCIusSKN3vto6.jpg', 'Letterkenny follows Wayne, a good-ol’ country boy in Letterkenny, Ontario trying to protect his homegrown way of life on the farm, against a world that is constantly evolving around him. The residents of Letterkenny belong to one of three groups: Hicks, Skids, and Hockey Players. The three groups are constantly feuding with each other over seemingly trivial matters; often ending with someone getting their ass kicked.', NULL, NULL, 20.3702, 7.962, 0, 1.06550000000000011e+01, '2026-07-20 01:02:04', '2026-11-23 03:03:39')
