VALUES (588182, 'tt10262648', NULL, 'Compartment No. 6', 'Hytti nro 6', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/3KUsYQmQXVCMrnGnQIoqkj5MJUP.jpg', 'https://image.tmdb.org/t/p/original/h0uGdJyZ5o74p0E600oKYyaoDhw.jpg', 'A young Finnish woman escapes an enigmatic love affair in Moscow by boarding a train to the arctic port of Murmansk. Forced to share the long ride and a tiny sleeping car with a larger than life Russian miner, the unexpected encounter leads the occupants of Compartment No. 6 to face major truths about human connection.', NULL, NULL, 2.1237, 6.99, 0, 8.775, '2026-09-01 03:44:37', '2026-11-23 03:03:39')
