VALUES (516486, 'tt6048922', NULL, 'Greyhound', 'Greyhound', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/kjMbDciooTbJPofVXgAoFjfX8Of.jpg', 'https://image.tmdb.org/t/p/original/xXBnM6uSTk6qqCf0SRZKXcga9Ba.jpg', 'A first-time captain leads a convoy of allied ships carrying thousands of soldiers across the treacherous waters of the "Black Pit" to the front lines of WWII. With no air cover protection for 5 days, the captain and his convoy must battle the surrounding enemy Nazi U-boats in order to give the allies a chance to win the war.', NULL, NULL, 13.6346, 7.415, 0, 10.795, '2026-10-18 22:36:17', '2026-11-23 03:03:39')
